const FlatHome={walls:[{x:80,y:100,w:1280,h:18},{x:80,y:100,w:18,h:870},{x:1342,y:100,w:18,h:870},{x:80,y:952,w:600,h:18},{x:800,y:952,w:560,h:18},{x:490,y:100,w:18,h:260},{x:490,y:460,w:18,h:230},{x:490,y:790,w:18,h:180},{x:950,y:100,w:18,h:260},{x:950,y:460,w:18,h:230},{x:950,y:790,w:18,h:180},{x:80,y:570,w:180,h:18},{x:360,y:570,w:130,h:18},{x:968,y:570,w:140,h:18},{x:1208,y:570,w:150,h:18}],furniture:FurnitureData.items.filter(f=>f.b).map(f=>({x:f.b[0],y:f.b[1],w:f.b[2],h:f.b[3]}))};
function flatFurnitureArt(){const F=FurnitureData,[W,H]=F.size,img=f=>{const [sx,sy,sw,sh]=f.s,[x,y,w,h]=f.d;return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" preserveAspectRatio="none"><image href="${F.atlas}" width="${W}" height="${H}"/></svg>`};return F.items.filter(f=>f.m==='f').map(img).join('')+F.items.filter(f=>f.m!=='f').sort((a,b)=>(a.d[1]+a.d[3])-(b.d[1]+b.d[3])).map(img).join('')}
function flatHomeArt(){const rooms=[['厨房',100,120,390,450,'#fff5e9'],['客厅',508,120,442,830,'#fff4f8'],['卧室',968,120,374,450,'#fff0f6'],['浴室',100,588,390,364,'#f1faf9'],['衣帽间',968,588,374,364,'#f8f3fc']];return `<svg class="world-art flat-home" viewBox="0 0 1448 1086" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="planks" width="70" height="120" patternUnits="userSpaceOnUse"><path d="M0 0H70V120H0Z" fill="none" stroke="#dfc8b71a" stroke-width="2"/></pattern></defs><rect width="1448" height="1086" fill="#f6edf1"/>${rooms.map(([name,x,y,w,h,c])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`).join('')}<rect x="100" y="120" width="1242" height="832" fill="url(#planks)"/>${FlatHome.walls.map(b=>`<rect x="${b.x}" y="${b.y}" width="${b.w}" height="${b.h}" rx="3" fill="#dcb9c8"/>`).join('')}${flatFurnitureArt()}<text x="690" y="1005" font-size="22" fill="#ad8295">花园入口</text><path d="M680 952h120" stroke="#e9d1b4" stroke-width="12"/></svg>`}
const priorHomeArt=homeMapArt;homeMapArt=room=>room==='inside'?flatHomeArt():priorHomeArt(room);
PalaisHomeWorld.maps.inside={width:1448,height:1086,spawn:{x:740,y:870},door:{x:740,y:910},blocks:[...FlatHome.walls,...FlatHome.furniture],walkAreas:[[[100,120],[1340,120],[1340,950],[100,950]]]};
PalaisHomeWorld.maps.garden.blocks.push({x:30,y:980,w:1388,h:65},{x:30,y:870,w:38,h:110},{x:1380,y:630,w:38,h:350});
function openHomeFishing(){let phase='ready',start=0;const d=homePanel(`<div class="eyebrow">A QUIET MOMENT</div><h2>池畔钓鱼</h2><p id="fishStatus">抛竿后等待咬钩，看见提示就收竿。钓到的鱼记录在家园日记。</p><button class="primary full" id="castFish">抛竿</button>`),b=d.querySelector('#castFish'),s=d.querySelector('#fishStatus');let timer;b.onclick=()=>{if(phase==='ready'){phase='waiting';b.textContent='等待咬钩…';s.textContent='浮漂轻轻晃动，耐心等一等。';timer=setTimeout(()=>{if(!d.open)return;phase='bite';start=performance.now();b.textContent='咬钩了！立即收竿';s.textContent='现在点击收竿！'},1800+Math.random()*3000)}else if(phase==='waiting'){s.textContent='还没有咬钩，再耐心等一下。'}else if(phase==='bite'){const caught=performance.now()-start<2200;try{if(caught)livingCommit(wallet,livingEvent(living,'用户在花园池塘钓到一条小鱼。'));s.textContent=caught?'钓到一条小鱼！已写入家园记录。':'鱼游走了，下次再试。';phase='ready';b.textContent='再抛一次'}catch(e){s.textContent=e.message}}};d.addEventListener('close',()=>clearTimeout(timer),{once:true})}
const mountBeforeFlat=renovationMount;renovationMount=function(g){mountBeforeFlat(g);const coords={roomKitchen:[390,470],roomWardrobe:[1130,810],roomBedroom:[1130,470],roomBath:[310,810],roomDesk:[740,340],roomStorage:[205,522]};if(g.player.room==='inside'){for(const [id,[x,y]]of Object.entries(coords)){const b=$('#'+id);if(!b)continue;b.style.left=x+'px';b.style.top=y+'px';const action={roomKitchen:openLivingKitchen,roomWardrobe:openChibiSelector,roomBedroom:()=>roomLifeAction('一起在卧室休息'),roomBath:()=>roomLifeAction('在浴室洗漱'),roomDesk:()=>roomLifeAction('一起工作学习'),roomStorage:openLivingKitchen}[id];b.onclick=()=>homeWalkTo({x,y},action)}const p=$('#petBed');p.style.left='850px';p.style.top='790px';p.onclick=()=>homeWalkTo({x:850,y:790},()=>openHomePanel('pet'))}else{for(const [id,label,x,y,action]of [['pondFishing','池塘 · 钓鱼',1040,800,openHomeFishing],['gardenPetCare','宠物角 · 领养与照料',1270,720,()=>openHomePanel('pet')]]){const b=document.createElement('button');b.id=id;b.className='world-hotspot room-action';b.textContent=label;b.style.left=x+'px';b.style.top=y+'px';b.onclick=()=>homeWalkTo({x,y},action);$('#gameWorld').append(b)}}};
